def control(obs):
    c=obs['progress']['covered']
    h=obs['hitch_deg']
    if st['c0'] is None: st['c0']=c
    if st['ph']==0:
        if c<st['c0']-2.5:
            st['ph']=1
        else:
            return (0,1.0,0)
    if st['ph']==1:
        if obs['motion']['hold_s']>0 or obs['motion']['v_mps']>0.05:
            return (0,0,0)
        st['ph']=2
    g=obs['rig'].get('screen_gaze_deg')
    cam=obs['views'].get('camera') if obs.get('views') else None
    if cam:
        ox,oy=cam['origin']
        L=[];R=[]
        for b,d in cam['walls']:
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            if -10<x<-3:
                if y>0: L.append(y)
                else: R.append(y)
        if L and R:
            mid=(min(L)+max(R))/2
            st['tgt']=max(-10,min(10,5*mid))
    s=max(-34,min(34,1.8*(h-st['tgt'])))
    return (s,-0.7,g if g is not None else -23)

